protocol Store { func save(id: String); func load(id: String) -> String }

struct CountingStore: Store {
    let inner: any Store                          // contained object, injected
    private(set) var count = 0
    func save(id: String) { count += 1; inner.save(id: id) }    // hand-written forward
    func load(id: String) -> String { inner.load(id: id) }      // hand-written forward
}
